set SQL_SAFE_UPDATES=0;
UPDATE `EMAIL_SCENARIO` SET `BODY`='Dear {{inviteClient.FirstName}} {{inviteClient.LastName}},\n\n{{inviteClient.loginUsername}} @{{inviteClient.vendorOrgName}} is using SourceLead a Global Talent Harvesting Platform to Manage Human Resource for their company.\n\nThis email is being sent to you because {{inviteClient.loginUsername}} @{{inviteClient.vendorOrgName}} is using SourceLead to Manage their resource including Project management,Applicaiton Tracking,Time Tracking,Billing,Crowd Sourcing etc.
\nSourceLead makes it easy for teams to work more efficiently by Managing the Resource.\nOver 8,000 remote teams uses it daily.\n\nPlease find your user id and temporary password below to login to the sourcelead platform and setup your organization.\n\nUsername : {{inviteClient.userName}}\nPassword  : {{inviteClient.Password}}\n{{inviteClient.acceptURL}}\n\n',`SIGNATURE`='Best Regards\n{{inviteClient.loginUsername}}\n{{inviteClient.vendorOrgName}}' WHERE `UNIQUE_SCENARIO_NAME`='Accept Client Invitation' and `ENTITY_TYPE`='Email';